const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const region = ee.Geometry.Rectangle([-7.5, 36.0, -1.5, 38.5]); // Southern Iberian Peninsula

  // Date ranges
  const date2023 = ['2023-03-25', '2023-04-23'];
  const dateLongTerm = ['2000-03-25', '2010-04-23'];

  // 2. Data Acquisition - Use MODIS for long-term consistency
  const modis = ee.ImageCollection('MODIS/061/MOD13Q1')
    .select('NDVI')
    .filterBounds(region);

  const ndvi2023 = modis.filterDate(date2023[0], date2023[1]);
  const ndviLongTerm = modis.filterDate(dateLongTerm[0], dateLongTerm[1]);

  // Check data availability
  const count2023 = ndvi2023.size().getInfo();
  const countLongTerm = ndviLongTerm.size().getInfo();

  console.log(`2023 Images: ${count2023}, Long-term Images: ${countLongTerm}`);

  if (count2023 === 0 || countLongTerm === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Processing - Calculate mean NDVI
  const mean2023 = ndvi2023.mean().multiply(0.0001); // MODIS scaling
  const meanLongTerm = ndviLongTerm.mean().multiply(0.0001);

  // Calculate pixel counts to detect C2
  const countStats2023 = mean2023.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: region,
    scale: 1000,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  const countStatsLT = meanLongTerm.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: region,
    scale: 1000,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  console.log(`Valid pixels - 2023: ${countStats2023}, Long-term: ${countStatsLT}`);

  if (countStats2023 === 0 || countStatsLT === 0) {
    console.log("<answer>C2</answer>");
    return;
  }

  // 4. Calculation - Get mean NDVI values
  const ndviVal2023 = mean2023.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: region,
    scale: 1000,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  const ndviValLongTerm = meanLongTerm.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: region,
    scale: 1000,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  // 5. Validation & Final Answer
  console.log(`NDVI 2023: ${ndviVal2023?.toFixed(3)}, Long-term: ${ndviValLongTerm?.toFixed(3)}`);

  // Check for invalid values
  if (ndviVal2023 === null || ndviValLongTerm === null || 
      isNaN(ndviVal2023) || isNaN(ndviValLongTerm) ||
      ndviVal2023 < -1 || ndviVal2023 > 1 || 
      ndviValLongTerm < -1 || ndviValLongTerm > 1) {
    console.log("<answer>C3</answer>");
    return;
  }

  // Compare values - 2023 higher than long-term average means healthier
  if (ndviVal2023 > ndviValLongTerm) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
